              title: "类型注解（typing）+ AI 辅助写注解",
              description: "类型注解让你一眼看出函数的输入是什么类型、输出是什么类型。不用再猜「这个参数是 DataFrame 还是 dict？」——注解就是函数的「使用说明书」。",
              prompt: `=== 第36天：类型注解 ===

【每日学习时长】约3小时

【学习目的】
类型注解不是给 Python 看的，是给人看的。当你三个月后回来看自己写的代码，类型注解就是最好的文档。今天的核心认知：好的注解让函数「自解释」——不用读实现代码，只看签名就知道怎么用。

【所需工具】
Python 3.x + typing（内置模块）+ mypy（可选）

【核心概念】
- 基础注解：def func(x: int) -> str: 接收 int，返回 str
- 复杂注解：def clean(df: pd.DataFrame) -> pd.DataFrame
- Optional[str]：参数可能是 str，也可能是 None
- List[dict]：列表里面装字典
- ★ 让 AI 帮你给一段无注解的代码加注解，然后逐行理解每个注解的含义

【练习任务】
- 给之前写的清洗函数、指标函数加类型注解
- 用 Optional 处理可能为空的参数
- 运行 mypy 检查类型是否正确
- 让 AI 给一段无注解代码加注解，然后你审查`,
              tasks: ["给清洗函数和指标函数加类型注解", "理解 Optional 和复杂类型注解", "数学：手动计算一组收益率的均值和方差"]
